from __future__ import annotations

import base64
import io
import shutil
import tarfile
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
PAYLOAD = """"""

archive = base64.b64decode(PAYLOAD)
with tarfile.open(fileobj=io.BytesIO(archive), mode="r:gz") as tar:
    tar.extractall(ROOT)

config_path = ROOT / ".pre-commit-config.yaml"
if config_path.is_dir():
    shutil.rmtree(config_path)
elif config_path.exists():
    config_path.unlink()
config_path.write_text(
    """minimum_pre_commit_version: '3.5.0'\nrepos:\n  - repo: local\n    hooks:\n      - id: python-compile\n        name: Python syntax check\n        entry: python -m py_compile whatsapp_helpers.py whatsapp_event.py tests/test_whatsapp_markdown.py\n        language: system\n        pass_filenames: false\n      - id: whatsapp-markdown-tests\n        name: WhatsApp Markdown regression tests\n        entry: python -m unittest -v tests/test_whatsapp_markdown.py\n        language: system\n        pass_filenames: false\n""",
    encoding="utf-8",
)

for relative in (
    ".github/scripts/apply_streaming_robustness.py",
    ".github/workflows/apply-streaming-robustness.yml",
):
    path = ROOT / relative
    if path.exists():
        path.unlink()
try:
    (ROOT / ".github/scripts").rmdir()
except OSError:
    pass
